<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('#empForm'),panels=[...document.querySelectorAll('.emp-panel')],marks=[...document.querySelectorAll('.step-btn')],prev=document.querySelector('#prev'),next=document.querySelector('#next'),save=document.querySelector('#save'),errors=@json($errors->toArray());let step=0;
const rules={name:{minLength:3,maxLength:191,pattern:"[A-Za-zÀ-ÿ .'-]+"},biometric_code:{maxLength:50,pattern:'[A-Za-z0-9_-]+'},email:{maxLength:191},password:{minLength:6,maxLength:72},phone:{maxLength:30,pattern:'\\+?[0-9][0-9 ()\\.-]{6,28}'},emergency_contact_phone:{maxLength:30,pattern:'\\+?[0-9][0-9 ()\\.-]{6,28}'},postal_code:{maxLength:20,pattern:'[A-Za-z0-9 -]+'},account_number:{maxLength:100,pattern:'[A-Za-z0-9 -]+'},bank_identifier_code:{maxLength:100,pattern:'[A-Za-z0-9-]+'},base_salary:{min:'0',max:'999999999999.99'}};
Object.entries(rules).forEach(([name,attrs])=>{const field=form.elements[name];if(field)Object.entries(attrs).forEach(([key,value])=>field[key]=value)});const password=form.elements.password;if(password){const group=document.createElement('div');group.className='input-group';password.parentNode.insertBefore(group,password);group.appendChild(password);const toggle=document.createElement('button');toggle.type='button';toggle.className='btn btn-light';toggle.innerHTML='<span aria-hidden="true">👁</span>';toggle.setAttribute('aria-label','Show password');toggle.title='Show password';group.appendChild(toggle);toggle.addEventListener('click',()=>{const visible=password.type==='text';password.type=visible?'password':'text';toggle.querySelector('span').textContent=visible?'👁':'🙈';toggle.setAttribute('aria-label',visible?'Show password':'Hide password');toggle.title=visible?'Show password':'Hide password';password.focus()})}const dob=form.elements.date_of_birth,joining=form.elements.date_of_joining,today=new Date().toISOString().slice(0,10);if(dob)dob.max=today;if(joining)joining.max=today;form.querySelector('[name=profile_image]').accept='.jpg,.jpeg,.png,.webp';form.querySelectorAll('[name="document_file[]"]').forEach(f=>f.accept='.pdf,.jpg,.jpeg,.png,.doc,.docx');
function show(value=step){step=Math.max(0,Math.min(4,value));panels.forEach((p,i)=>p.classList.toggle('active',i===step));marks.forEach((m,i)=>{m.classList.toggle('active',i===step);m.classList.toggle('done',i<step)});prev.style.visibility=step?'visible':'hidden';next.style.display=step===4?'none':'block';save.style.display=step===4?'block':'none'}
function clearError(field){field.classList.remove('is-invalid');field.parentElement.querySelector('.field-error')?.remove();field.setCustomValidity('')}
function setError(field,message){if(!field)return;field.classList.add('is-invalid');field.setCustomValidity(message);if(!field.parentElement.querySelector('.field-error'))field.insertAdjacentHTML('afterend','<span class="field-error"></span>');field.parentElement.querySelector('.field-error').textContent=message;const index=panels.findIndex(p=>p.contains(field));if(index>=0)marks[index].classList.add('has-error')}
Object.entries(errors).forEach(([key,messages])=>{const base=key.replace(/\.\d+$/, '[]');const fields=[...form.querySelectorAll(`[name="${CSS.escape(base)}"]`)];const match=key.match(/\.(\d+)$/);setError(match?fields[Number(match[1])]:form.elements[key]||fields[0],messages[0])});const firstError=panels.findIndex(p=>p.querySelector('.is-invalid'));if(firstError>=0)show(firstError);
form.querySelectorAll('input,select,textarea').forEach(field=>field.addEventListener('input',()=>clearError(field)));
function validatePanel(index){let valid=true;for(const field of panels[index].querySelectorAll('input,select,textarea')){clearError(field);if(!field.checkValidity()){setError(field,field.validationMessage);valid=false}}if(index===0){if(dob?.value&&dob.value>=today){setError(dob,'Date of Birth must be before today.');valid=false}const image=form.elements.profile_image,file=image.files[0];if(file&&file.size>2097152){setError(image,'Profile image must not exceed 2MB.');valid=false}if(file&&!['image/jpeg','image/png','image/webp'].includes(file.type)){setError(image,'Profile image must be JPG, PNG or WEBP.');valid=false}}if(index===1&&joining?.value&&dob?.value&&joining.value<=dob.value){setError(joining,'Joining date must be after Date of Birth.');valid=false}if(index===4){const types=[...form.querySelectorAll('[name="document_type_id[]"]')],files=[...form.querySelectorAll('[name="document_file[]"]')];types.forEach((type,i)=>{if(type.value&&!files[i].files.length){setError(files[i],'Choose a file for this document type.');valid=false}if(!type.value&&files[i].files.length){setError(type,'Select a document type for this file.');valid=false}if(files[i].files[0]?.size>5242880){setError(files[i],'Document must not exceed 5MB.');valid=false}})}return valid}
next.onclick=()=>{if(validatePanel(step)){show(step+1)}};prev.onclick=()=>show(step-1);marks.forEach((mark,i)=>mark.onclick=()=>{if(i<=step)show(i)});form.addEventListener('submit',event=>{for(let i=0;i<panels.length;i++){if(!validatePanel(i)){event.preventDefault();show(i);panels[i].querySelector('.is-invalid')?.focus();return}}});show(step)})</script>
